1	export interface Customer {
2	  readonly yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  readonly type: string;
7	  // Declared by the scenario input schema and read only by the claim-side
8	  // dragon-material clause, which is not yet active. No premium rule reads it.
9	  readonly material?: string;
10	  readonly cursed?: boolean;
11	  readonly enchantment?: number;
12	}
13	
14	const PROCESSING_FEE = 5;
15	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
16	const LOYALTY_DISCOUNT_RATE = 0.2;
17	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
18	const LONG_STANDING_MINIMUM_YEARS = 2;
19	const CURSE_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
21	const HIGH_ENCHANTMENT_LEVEL = 5;
22	
23	const MAIN_ITEM_BASE_PREMIUM_PRICE_LIST: Readonly<Record<string, number>> = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	};
29	
30	const COMPONENT_INSURANCE_VALUE = 250;
31	
32	const MAIN_ITEM_INSURANCE_VALUE_PRICE_LIST: Readonly<Record<string, number>> = {
33	  sword: 1000,
34	  amulet: 600,
35	  staff: 800,
36	  potion: 400,
37	};
38	
39	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
40	const COMPONENT_BASE_PREMIUM = 25;
41	const ALIKE_COMPONENTS_PER_BLOCK = 3;
42	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
43	
44	function isComponent(item: Item): boolean {
45	  return COMPONENT_TYPES.includes(item.type);
46	}
47	
48	function mainItemsOf(items: readonly Item[]): readonly Item[] {
49	  return items.filter((item) => !isComponent(item));
50	}
51	
52	function componentsOf(items: readonly Item[]): readonly Item[] {
53	  return items.filter(isComponent);
54	}
55	
56	function mainItemBasePremiumOf(item: Item): number {
57	  return MAIN_ITEM_BASE_PREMIUM_PRICE_LIST[item.type] ?? 0;
58	}
59	
60	// "Alike" means the same item type, not the same family: 2 runes + 1 moonstone
61	// form no block.
62	function countAlikeComponents(components: readonly Item[]): Map<string, number> {
63	  const counts = new Map<string, number>();
64	  for (const component of components) {
65	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
66	  }
67	  return counts;
68	}
69	
70	function alikeComponentsBasePremiumOf(alikeCount: number): number {
71	  if (alikeCount === ALIKE_COMPONENTS_PER_BLOCK) {
72	    return COMPONENT_BLOCK_BASE_PREMIUM;
73	  }
74	  return alikeCount * COMPONENT_BASE_PREMIUM;
75	}
76	
77	function componentsBasePremiumOf(components: readonly Item[]): number {
78	  let total = 0;
79	  for (const alikeCount of countAlikeComponents(components).values()) {
80	    total += alikeComponentsBasePremiumOf(alikeCount);
81	  }
82	  return total;
83	}
84	
85	function isCursed(item: Item): boolean {
86	  return item.cursed === true;
87	}
88	
89	function isHighlyEnchanted(item: Item): boolean {
90	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
91	}
92	
93	function itemSpecificSurchargesOn(item: Item, itemBasePremium: number): number {
94	  const curse = isCursed(item) ? itemBasePremium * CURSE_SURCHARGE_RATE : 0;
95	  const highEnchantment = isHighlyEnchanted(item)
96	    ? itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
97	    : 0;
98	  return curse + highEnchantment;
99	}
100	
101	function riskAdjustedMainItemPremiumOf(mainItem: Item): number {
102	  const itemBasePremium = mainItemBasePremiumOf(mainItem);
103	  return itemBasePremium + itemSpecificSurchargesOn(mainItem, itemBasePremium);
104	}
105	
106	function riskAdjustedMainItemsPremiumOf(mainItems: readonly Item[]): number {
107	  return mainItems.reduce((sum, mainItem) => sum + riskAdjustedMainItemPremiumOf(mainItem), 0);
108	}
109	
110	function mainItemsBasePremiumOf(mainItems: readonly Item[]): number {
111	  return mainItems.reduce((sum, mainItem) => sum + mainItemBasePremiumOf(mainItem), 0);
112	}
113	
114	// The policy base premium is the sum of all item base premiums, before any
115	// item-specific surcharge. Policy-wide modifiers are percentages of it.
116	function policyBasePremiumOf(items: readonly Item[]): number {
117	  return mainItemsBasePremiumOf(mainItemsOf(items)) + componentsBasePremiumOf(componentsOf(items));
118	}
119	
120	// Only main items carry item-specific surcharges: components have no curse flag,
121	// enchantment level, or material in the MHPCO item model.
122	function riskAdjustedItemsPremiumOf(items: readonly Item[]): number {
123	  return (
124	    riskAdjustedMainItemsPremiumOf(mainItemsOf(items)) +
125	    componentsBasePremiumOf(componentsOf(items))
126	  );
127	}
128	
129	// Deliberately takes no customer: "first insurance" is a property of the quoted
130	// item, not of the customer's history. Each item in a quote is treated as a first
131	// insurance, so the surcharge applies even on a follow-up contract.
132	function firstInsuranceSurchargeOn(policyBasePremium: number): number {
133	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
134	}
135	
136	function isLongStanding(customer: Customer): boolean {
137	  return customer.yearsWithMHPCO >= LONG_STANDING_MINIMUM_YEARS;
138	}
139	
140	function loyaltyDiscountOn(customer: Customer, policyBasePremium: number): number {
141	  return isLongStanding(customer) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
142	}
143	
144	// A contract after the customer's first earns the follow-up discount; the first
145	// contract does not.
146	function followUpContractDiscountOn(precedingContracts: number, policyBasePremium: number): number {
147	  return precedingContracts > 0 ? policyBasePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
148	}
149	
150	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) are
151	// percentages of the policy base premium; the net signed sum is what the premium
152	// carries.
153	function policyWideModifiersOn(
154	  customer: Customer,
155	  precedingContracts: number,
156	  policyBasePremium: number,
157	): number {
158	  return (
159	    firstInsuranceSurchargeOn(policyBasePremium) -
160	    loyaltyDiscountOn(customer, policyBasePremium) -
161	    followUpContractDiscountOn(precedingContracts, policyBasePremium)
162	  );
163	}
164	
165	function roundPremiumInOfficesFavour(premium: number): number {
166	  return Math.ceil(premium);
167	}
168	
169	export function quote(
170	  customer: Customer,
171	  items: readonly Item[],
172	  precedingContracts = 0,
173	): number {
174	  return roundPremiumInOfficesFavour(
175	    riskAdjustedItemsPremiumOf(items) +
176	      policyWideModifiersOn(customer, precedingContracts, policyBasePremiumOf(items)) +
177	      PROCESSING_FEE,
178	  );
179	}
180	
181	// The insurance sum is the sum of the items' unmodified insurance values; the
182	// component block discount affects the premium only, not the insurance sum.
183	export function insuranceSumOf(items: readonly Item[]): number {
184	  return items.reduce(
185	    (sum, item) =>
186	      sum +
187	      (isComponent(item)
188	        ? COMPONENT_INSURANCE_VALUE
189	        : (MAIN_ITEM_INSURANCE_VALUE_PRICE_LIST[item.type] ?? 0)),
190	    0,
191	  );
192	}
