cp src/claim.ts /tmp/claim.ts.bak && python3 - << 'PYEOF'
import re
p = "src/claim.ts"
s = open(p).read()
old = '''function reimbursementFor(damage: Damage): number {
  return Math.max(damage.amount - DEDUCTIBLE_PER_DAMAGE_EVENT, 0);
}

export function settle(policy: Policy, incident: Incident): ClaimSettlement {
  const desired = incident.damages.reduce((sum, damage) => sum + reimbursementFor(damage), 0);
  const payout = roundPayoutInOfficesFavour(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
'''
new = '''function reimbursementFor(damage: Damage): number {
  return Math.max(damage.amount - DEDUCTIBLE_PER_DAMAGE_EVENT, 0);
}

function desiredReimbursementFor(incident: Incident): number {
  return incident.damages.reduce((sum, damage) => sum + reimbursementFor(damage), 0);
}

// The cap limits what a single claim pays out, and every payout consumes it:
// successive claims against the same policy share one cap.
function payoutLimitedToRemainingCap(desiredReimbursement: number, remainingCap: number): number {
  return Math.min(desiredReimbursement, remainingCap);
}

function consumeCap(policy: Policy, payout: number): number {
  policy.remainingCap -= payout;
  return policy.remainingCap;
}

export function settle(policy: Policy, incident: Incident): ClaimSettlement {
  const payout = roundPayoutInOfficesFavour(
    payoutLimitedToRemainingCap(desiredReimbursementFor(incident), policy.remainingCap),
  );
  return { payout, remainingCap: consumeCap(policy, payout) };
}
'''
assert old in s
open(p, "w").write(s.replace(old, new))
PYEOF
